          ]
        },
        {
          "proposicao": "O modelo fenomenológico relaciona o escoamento de fluido com partículas, a retenção no meio poroso e a permeabilidade inicial para explicar retenção de material e declínio de injetividade.",
          "trechos": [
            "E6603c1879bab28aa:692:1392",
            "E6603c1879bab28aa:1392:2086",
            "E6603c1879bab28aa:2086:2168"
          ],
          "condicoes": [
            "a formulação depende de variáveis do sistema fluido/reservatório, como concentração de partículas e coeficiente de filtração"
          ],
          "limites": [
            "o alcance do trecho é a interação água-reservatório; não traz dados sobre cavitação, sucção, caixas de mar ou desempenho de bombas de captação"
          ]
        }
      ]
    },
    {
      "id": "Ee02d45e14efadca2",
      "pertinente": true,
      "tipo": "recomendacao",
      "achados": [
        {
          "proposicao": "Na desaeração a vácuo, a eliminação de CO2 dissolvido pode desequilibrar o balanço CO2/CO3/HCO3 e teoricamente precipitar carbonato de cálcio em água do mar.",
          "trechos": [
